package com.hisen.utils;import Java.io.File;import Java.io.FileInputStream;import Java.io.FileNotFoundException;import Java.io.FileOutputStream;import Java.io.IOException;import Java.io.InputStream;import Java.io.OutputStream;import Java.util.zip.ZipEntry;import Java.util.zip.ZipFile;import Java.util.zip.ZipInputStream;import Java.util.zip.ZipOutputStream;import org.apache.commons.io.IOUtils;import org.junit.Test;/** * 文件夹压缩解压工具 * Created by hisenyuan on 2017/4/20 at 17:27. */public class ZipOrUnZipFileUtil &#123; private InputStream is; private ZipOutputStream zos; private int lastIndexOf; @Test public void testZipOrUnZipFile() &#123; //分隔符，windows linux下有所不同 String separator = File.separator; //想要压缩的文件所在目录 C:\1\hisenyuan String folderPath = &quot;c:&quot; + separator + &quot;1&quot; + separator + &quot;hisenyuan&quot;; //压缩文件路径：C:\1\hisenyuan\hisenyuan.zip String zipFilePath = &quot;c:&quot; + separator + &quot;1&quot; + separator + &quot;hisenyuan&quot; + &quot;.zip&quot;; //解压文件所在的目录 E:\file\hisenyuan String newPath = &quot;e:&quot; + separator + &quot;file&quot; + separator + &quot;hisenyuan&quot;; unZipFile(zipFilePath, newPath); zipFile(folderPath); &#125; /** * 压缩文件 * * @param filePath 压缩文件夹的路径 */ private void zipFile(String filePath) &#123; File file = new File(filePath); File zipFile = new File(filePath + &quot;.zip&quot;); lastIndexOf = file.getAbsolutePath().length() + 1; try &#123; zos = new ZipOutputStream(new FileOutputStream(zipFile)); zos.setComment(&quot;log&quot;); long start = System.currentTimeMillis(); listAllFile(filePath); long stop = System.currentTimeMillis(); System.out.println(&quot;zip done，time：&quot; + (stop - start) / 1000 + &quot;s&quot;); &#125; catch (FileNotFoundException e) &#123; e.printStackTrace(); &#125; finally &#123; IOUtils.closeQuietly(zos, is); &#125; &#125; /** * 循环遍历当前文件夹下的所有文件，使用递归 */ private void listAllFile(String filePath) &#123; File file = new File(filePath); if (file.exists()) &#123; File[] files = file.listFiles(); if (files == null) &#123; System.out.println(&quot;folder is null&quot;); &#125; else &#123; for (File file2 : files) &#123; if (file2.isDirectory()) &#123; listAllFile(file2.getAbsolutePath()); &#125; else &#123; String file3 = file2.getAbsolutePath(); try &#123; is = new FileInputStream(file3); //在zip压缩包当中出现的文件名 String name = file3.substring(lastIndexOf, file3.length()); System.out.println(&quot;name:&quot; + name); zos.putNextEntry(new ZipEntry(name)); int temp; int bufferSize = 1024 * 5; byte[] buffer = new byte[bufferSize]; while ((temp = is.read(buffer, 0, bufferSize)) != -1) &#123; zos.write(buffer, 0, temp); zos.flush(); &#125; &#125; catch (IOException e) &#123; e.printStackTrace(); &#125; &#125; &#125; &#125; &#125; &#125; /** * 解压文件 * * @param filePath 压缩文件所在目录 * @param newPath 想解压到那个目录 */ private void unZipFile(String filePath, String newPath) &#123; //压缩文件所在的父目录 String oldPath = new File(filePath).getParentFile().toString(); File outFile; ZipInputStream zipInputStream = null; OutputStream outputStream = null; InputStream inputStream = null; ZipEntry zipEntry; try &#123; ZipFile zipFile = new ZipFile(filePath); zipInputStream = new ZipInputStream(new FileInputStream(filePath)); while (null != (zipEntry = zipInputStream.getNextEntry())) &#123; System.out.println(&quot;解压缩&quot; + zipEntry.getName() + &quot;文件。&quot;); //newPath为空就代表解压在当前目录 if (&quot;&quot;.equals(newPath) || newPath.isEmpty()) &#123; outFile = new File(oldPath + zipEntry.getName()); &#125; else &#123; //防止传入的目录不存在 File file = new File(newPath); if (!file.exists()) &#123; file.mkdir(); &#125; outFile = new File(newPath + File.separator + zipEntry.getName()); &#125; //判断当前文件路径是否存在，不存在就创建 buildFile(outFile); inputStream = zipFile.getInputStream(zipEntry); outputStream = new FileOutputStream(outFile); int temp; int bufferSize = 1024 * 5; byte[] buffer = new byte[bufferSize]; while ((temp = inputStream.read(buffer, 0, bufferSize)) != -1) &#123; outputStream.write(buffer, 0, temp); &#125; &#125; &#125; catch (IOException e) &#123; e.printStackTrace(); &#125; finally &#123; IOUtils.closeQuietly(inputStream, outputStream, zipInputStream); &#125; &#125; /** * 判断文件是否存在，不存在创建 */ private static void buildFile(File file) &#123; if (!file.exists()) &#123; File parent = file.getParentFile(); if (parent != null &amp;&amp; !parent.exists()) &#123; parent.mkdirs(); &#125; try &#123; file.createNewFile(); &#125; catch (IOException e) &#123; e.printStackTrace(); &#125; &#125; &#125;&#125;

重温经典，特意看了下为什么读文件非得不让等于 -1
fileChannelIn.read(byteBuffer) !&#x3D; -1
EOF &#x3D; End Of File，其默认值就是-1
这是一个约定好的结束符，不是认为改变的
代码建议使用大文件进行测试，看效果比较明显
@Testpublic void testCopy() &#123;    String oldFileName = &quot;/Users/hisenyuan/hisen/blog/source/_posts/Test-Java-Code.md&quot;;    String newFileName = &quot;/Users/hisenyuan/hisen/test/Test-Java-Code.md&quot;;    nioCopy(oldFileName, newFileName);    ioCopy(oldFileName, newFileName.replace(&quot;.md&quot;, &quot;.md.bak&quot;));    ioCopyByLine(oldFileName,newFileName.replace(&quot;.md&quot;,&quot;.bak.&quot; + System.currentTimeMillis()));&#125;/** * 利用NIO进行读写文件 * * @param oldFileName 原文件的路径 * @param newFileName 新文件的路径 */public static void nioCopy(String oldFileName, String newFileName) &#123;    try &#123;        FileChannel fileChannelIn = new FileInputStream(new File(oldFileName)).getChannel();        FileChannel fileChannelOut = new FileOutputStream(new File(newFileName)).getChannel();        //获取文件大小        long size = fileChannelIn.size();        System.out.printf(&quot;文件大小为：%s byte \n&quot;, size);        //缓冲        ByteBuffer byteBuffer = ByteBuffer.allocate(1024);        long start = System.currentTimeMillis();        while (fileChannelIn.read(byteBuffer) != -1) &#123;            //准备写            byteBuffer.flip();            fileChannelOut.write(byteBuffer);            //准备读            byteBuffer.clear();        &#125;        long end = System.currentTimeMillis();        System.out.printf(&quot;NIO方式复制完成，耗时 %s 秒\n&quot;, (end - start) / 1000);        //关闭        fileChannelIn.close();        fileChannelOut.close();    &#125; catch (FileNotFoundException e) &#123;        e.printStackTrace();    &#125; catch (IOException e) &#123;        e.printStackTrace();    &#125;&#125;/** * IO方式复制文件 * * @param oldFileName * @param newFileName */public static void ioCopy(String oldFileName, String newFileName) &#123;    try &#123;        FileInputStream fileInputStream = new FileInputStream(new File(oldFileName));        FileOutputStream fileOutputStream = new FileOutputStream(new File(newFileName));        long length = new File(oldFileName).length();        System.out.printf(&quot;文件大小为：%s byte \n&quot;, length);        byte[] buffer = new byte[1024];        long start = System.currentTimeMillis();        int len = 0;        //EOF = End Of File，其默认值就是-1        while ((len = fileInputStream.read(buffer)) != -1) &#123;            fileOutputStream.write(buffer, 0, len);        &#125;        long end = System.currentTimeMillis();        System.out.printf(&quot;IO方式复制完成，耗时 %s 秒\n&quot;, (end - start) / 1000);    &#125; catch (FileNotFoundException e) &#123;        e.printStackTrace();    &#125; catch (IOException e) &#123;        e.printStackTrace();    &#125;&#125;public static void ioCopyByLine(String oldFileName, String newFileName) &#123;    try &#123;        BufferedReader reader = new BufferedReader(new FileReader(oldFileName));        BufferedWriter writer = new BufferedWriter(new FileWriter(newFileName));        String line;        while ((line = reader.readLine()) != null) &#123;            writer.write(line);            writer.newLine();            writer.flush();        &#125;    &#125; catch (IOException e) &#123;        System.out.println(&quot;error:&quot; + e);    &#125;&#125;

