二、代码样例把全世界200+国家和地区的名字翻译为英文，并且入库
@AutowiredSmsCountryService countryService;@Testpublic void updateZhName()&#123;  // 有道翻译接口  String url = &quot;http://fanyi.youdao.com/openapi.do?keyfrom=xinlei&amp;key=759115437&amp;type=data&amp;doctype=json&amp;version=1.1&amp;q=&quot;;  // 查询出所有的英文国家名字  List&lt;SmsCountry&gt; countries = countryService.queryAllName();  // httpclient  CloseableHttpClient client = HttpClientBuilder.create().build();  // 翻译每个国家的名字，并且更新数据库  for (SmsCountry country:countries) &#123;    HttpGet request = new HttpGet(url + URLEncoder.encode(country.getName()));    try &#123;      CloseableHttpResponse response = client.execute(request);      String str = EntityUtils.toString(response.getEntity(), &quot;utf-8&quot;);      JSONObject jsonObject = JSON.parseObject(str);      // 取出json字符串中数组的值      String s = (String) jsonObject.getJSONArray(&quot;translation&quot;).get(0);      System.out.println(&quot;&gt;&gt;&gt;&gt;&gt; &quot; + s);      if (!StringUtil.isEmpty(s))&#123;      SmsCountry smsCountry = new SmsCountry();      smsCountry.setId(country.getId());      smsCountry.setNameZh(s);      countryService.updateNameById(smsCountry);      &#125;    &#125; catch (IOException e) &#123;      e.printStackTrace();    &#125;  &#125;&#125;

