/**   * 插入数据   */  @Test  public void testCreate()&#123;    DBObject obj = null;    for (int i = 1; i &lt;= 10; i++) &#123;      obj = new BasicDBObject(&quot;_id&quot;,i).append(&quot;name&quot;,&quot;hisen&quot;+i).append(&quot;age&quot;,i*5);      dbCollection.save(obj);    &#125;  &#125;  /**   * 查询所有   */  @Test  public void testReadAll()&#123;    DBCursor dbCursor = dbCollection.find();    while (dbCursor.hasNext())&#123;      System.out.println(dbCursor.next());    &#125;  &#125;  /**   * 修改记录   */  @Test  public void testUpdate()&#123;    BasicDBObject condition = new BasicDBObject(&quot;_id&quot;,10);    BasicDBObject res = new BasicDBObject(&quot;name&quot;, &quot;hisen10_new&quot;);    //若没有此语句，直接调用下面的语句，返回结果&#123; &quot;_id&quot; : 10 , &quot;name&quot; : &quot;hisen10_new&quot;&#125;    BasicDBObject res2 = new BasicDBObject(&quot;$set&quot;, res);    dbCollection.update(condition,res2);    System.out.println(dbCollection.findOne(new BasicDBObject(&quot;_id&quot;,10)));  &#125;  /**   * 删除记录   */  @Test  public void testDelete()&#123;    dbCollection.remove(new BasicDBObject(&quot;_id&quot;,10));    testReadAll();  &#125;  /**   * 根据主键查询   */  @Test  public void testReadOneWithId()&#123;    DBObject object = dbCollection.findOne(new BasicDBObject(&quot;_id&quot;,1));    System.out.println(object);  &#125;  /**   * 模糊查询 - 使用正则   */  @Test  public void testReadPuzzy()&#123;    Pattern pattern = Pattern.compile(&quot;^hisen1&quot;);    BasicDBObject basicDBObject = new BasicDBObject(&quot;name&quot;,pattern);    DBCursor dbCursor = dbCollection.find(basicDBObject);    while (dbCursor.hasNext())&#123;      System.out.println(dbCursor.next());    &#125;  &#125;  /**   * 清空集合   */  @Test  public void testDrop()&#123;    dbCollection.drop();    testReadAll();  &#125;

