--显示数据库当前连接数select count(*) from v$process;--显示数据库最大连接数select value from v$parameter where name =&#x27;processes&#x27;;--修改最大Oracle最大连接数:alter system set processes = 300 scope = spfile;--显示当前session连接数select count(*) from v$session;--查看当前有哪些用户正在使用数据SELECT osuser, a.username,cpu_time/executions/1000000||&#x27;s&#x27;, sql_fulltext,machine from v$session a, v$sqlarea b where a.sql_address =b.address order by cpu_time/executions desc;--查看连接oracle的所有机器的连接数select machine,count(*) from v$session group by machine;--查看连接oracle的所有机器的连接数和状态select machine,status,count(*) from v$session group by machine,status order by status;--查看消耗磁盘读取最多的SQL Top 5：select disk_reads,sql_text,SQL_FULLTEXTfrom (select sql_text,disk_reads,SQL_FULLTEXT,   dense_rank() over     (order by disk_reads desc) disk_reads_rank   from v$sql)where disk_reads_rank &lt;=5;--开始--通过linux中消耗资源高的进程号获取oracle消耗资源的sql语句：--1.linux中使用top命名查看oracle进程中消耗资源最高的进程号；--2.oracle中使用命令：select c.spid,a.p1,a.p1raw,a.p2,a.event,b.sql_text,b.SQL_FULLTEXT,b.SQL_IDfrom v$session a,v$sql b,v$process cwhere a.wait_class&lt;&gt;&#x27;Idle&#x27; and a.sql_id=b.sql_id and a.PADDR=c.addrorder by event;--3.查询结果显示出各个sql语句对应的进程号，从中找出top命令中对应消耗资源高的进程号即可找到相应的sql语句。--结束--判断回滚段竞争的SQL语句：（当Ratio大于2时存在回滚段竞争，需要增加更多的回滚段）select rn.name, rs.GETS, rs.WAITS, (rs.WAITS / rs.GETS) * 100 ratiofrom v$rollstat rs, v$rollname rnwhere rs.USN = rn.usn;---判断恢复日志竞争的SQL语句：（immediate_contention或wait_contention的值大于1时存在竞争）select name,(t.IMMEDIATE_MISSES / decode((t.IMMEDIATE_GETS + t.IMMEDIATE_MISSES),0,-1,(t.IMMEDIATE_GETS + t.IMMEDIATE_MISSES))) * 100 immediate_contention,(t.MISSES / decode((t.GETS + t.MISSES), 0, -1, (t.GETS + t.MISSES))) * 100 wait_contentionfrom v$latch twhere name in (&#x27;redo copy&#x27;, &#x27;redo allocation&#x27;);--判断表空间碎片：（如果最大空闲空间占总空间很大比例则可能不存在碎片，如果比例较小，且有许多空闲空间，则可能碎片很多）select t.tablespace_name,sum(t.bytes),max(t.bytes),count(*),max(t.bytes) / sum(t.bytes) radiofrom dba_free_space tgroup by t.tablespace_nameorder by t.tablespace_name;--确定命中排序域的次数：select t.NAME, t.VALUE from v$sysstat t where t.NAME like &#x27;sort%&#x27;--查看当前SGA值：SGA(System Global Area)系统全局区。这是一个非常庞大的内存区间select * from v$sga;--确定高速缓冲区命中率：（如果命中率低于70％，则应该加大init.ora参数中的DB_BLOCK_BUFFER的值）select 1 - sum(decode(name, &#x27;physical reads&#x27;, value, 0)) /(sum(decode(name, &#x27;db block gets&#x27;, value, 0)) +sum(decode(name, &#x27;consistent gets&#x27;, value, 0))) hit_ratiofrom v$sysstat twhere name in (&#x27;physical reads&#x27;, &#x27;db block gets&#x27;, &#x27;consistent gets&#x27;);--确定共享池中的命中率：（如果ratio1大于1时，需要加大共享池，如果ratio2大于10％时，需要加大共享池SHARED_POOL_SIZE）select * from(  select sum(pins) pins,  sum(reloads) reloads,  (sum(reloads) / sum(pins)) * 100 ratio1  from v$librarycache),(  select sum(gets) gets,  sum(getmisses) getmisses,  (sum(getmisses) / sum(gets)) * 100 ratio2  from v$rowcache)--查询INIT.ORA参数：select * from v$parameter;--求当前会话的SID，SERIAL#SELECT Sid, Serial# FROM V$sessionWHERE Audsid = Sys_Context(&#x27;USERENV&#x27;, &#x27;SESSIONID&#x27;);--查询session的OS进程ID(有输入)SELECT p.Spid &quot;OS Thread&quot;, b.NAME &quot;Name-User&quot;, s.Program, s.Sid, s.Serial#,s.Osuser, s.MachineFROM V$process p, V$session s, V$bgprocess bWHERE p.Addr = s.PaddrAND p.Addr = b.Paddr And (s.sid=&amp;1 or p.spid=&amp;1)UNION ALLSELECT p.Spid &quot;OS Thread&quot;, s.Username &quot;Name-User&quot;, s.Program, s.Sid,s.Serial#, s.Osuser, s.MachineFROM V$process p, V$session sWHERE p.Addr = s.PaddrAnd (s.sid=&amp;1 or p.spid=&amp;1)AND s.Username IS NOT NULL;--查看锁（lock）情况SELECT /*+ RULE */ Ls.Osuser Os_User_Name, Ls.Username User_Name,Decode(Ls.TYPE,&#x27;RW&#x27;, &#x27;Row wait enqueue lock&#x27;, &#x27;TM&#x27;, &#x27;DML enqueue lock&#x27;,&#x27;TX&#x27;, &#x27;Transaction enqueue lock&#x27;, &#x27;UL&#x27;, &#x27;User supplied lock&#x27;) Lock_Type,o.Object_Name OBJECT,Decode(Ls.Lmode,1, NULL, 2, &#x27;Row Share&#x27;, 3, &#x27;Row Exclusive&#x27;,4, &#x27;Share&#x27;, 5, &#x27;Share Row Exclusive&#x27;, 6, &#x27;Exclusive&#x27;,NULL) Lock_Mode,o.Owner, Ls.Sid, Ls.Serial# Serial_Num, Ls.Id1, Ls.Id2 FROM Sys.Dba_Objects o,(SELECT s.Osuser, s.Username, l.TYPE, l.Lmode, s.Sid, s.Serial#, l.Id1,l.Id2 FROM V$session s, V$lock lWHERE s.Sid = l.Sid) LsWHERE o.Object_Id = Ls.Id1AND o.Owner &lt;&gt; &#x27;SYS&#x27;ORDER BY o.Owner, o.Object_Name;--查看等待（wait）情况SELECT Ws.CLASS, Ws.COUNT COUNT, SUM(Ss.VALUE) Sum_ValueFROM V$waitstat Ws, V$sysstat SsWHERE Ss.NAME IN (&#x27;db block gets&#x27;, &#x27;consistent gets&#x27;)GROUP BY Ws.CLASS, Ws.COUNT;--求process/session的状态SELECT p.Pid, p.Spid, s.Program, s.Sid, s.Serial#FROM V$process p, V$session sWHERE s.Paddr = p.Addr;--查看表空间的名称及大小select t.tablespace_name, round(sum(bytes/(1024*1024)),0) ts_sizefrom dba_tablespaces t, dba_data_files dwhere t.tablespace_name = d.tablespace_namegroup by t.tablespace_name;--查看表空间物理文件的名称及大小select tablespace_name, file_id, file_name,round(bytes/(1024*1024),0) total_spacefrom dba_data_filesorder by tablespace_name;--查看回滚段名称及大小select segment_name, tablespace_name, r.status,(initial_extent/1024) InitialExtent,(next_extent/1024) NextExtent,--查看控制文件select name from v$controlfile;--查看日志文件select member from v$logfile;--查看表空间的使用情况select sum(bytes)/(1024*1024) as free_space,tablespace_namefrom dba_free_spacegroup by tablespace_name;SELECT A.TABLESPACE_NAME,A.BYTES TOTAL,B.BYTES USED, C.BYTES FREE,(B.BYTES*100)/A.BYTES &quot;% USED&quot;,(C.BYTES*100)/A.BYTES &quot;% FREE&quot;FROM SYS.SM$TS_AVAIL A,SYS.SM$TS_USED B,SYS.SM$TS_FREE CWHERE A.TABLESPACE_NAME=B.TABLESPACE_NAME AND A.TABLESPACE_NAME=C.TABLESPACE_NAME;--捕捉运行很久的SQLselect username,sid,opname,round(sofar*100 / totalwork,0) || &#x27;%&#x27; as progress,time_remaining,sql_textfrom v$session_longops , v$sqlwhere time_remaining &lt;&gt; 0and sql_address = addressand sql_hash_value = hash_value--耗资源的进程（top session）select s.schemaname schema_name, decode(sign(48 - command), 1,to_char(command), &#x27;Action Code #&#x27; || to_char(command) ) action, statussession_status, s.osuser os_user_name, s.sid, p.spid , s.serial# serial_num,nvl(s.username, &#x27;[Oracle process]&#x27;) user_name, s.terminal terminal,s.program program, st.value criteria_value from v$sesstat st, v$session s , v$process pwhere st.sid = s.sid and st.statistic# = to_number(&#x27;38&#x27;) and (&#x27;ALL&#x27; = &#x27;ALL&#x27;or s.status = &#x27;ALL&#x27;) and p.addr = s.paddr order by st.value desc, p.spid asc, s.username asc, s.osuser asc--查看有哪些实例在运行：select * from v$active_instances;

一、说明利用redis操作的原子性，实现Java 多线程并发的情况下实现计数器。
我本机测试多个线程操作之后，结果会出现一定的延迟，但是最终数字是ok的
应该是redis内部做了一个类似于队列的功能。
需要注意的是，得使用redis连接的线程池，不然会出现异常
这里有一个：JedisUtil 下面用到了
二、 代码实现2.1 redis操作类package com.hisen.thread.count_click_by_redis;import com.hisen.utils.JedisUtil;import redis.clients.jedis.JedisPool;/** * @author hisenyuan * @description 操作redis的线程类 */public class ClickRedis &#123;  /**   * 必须使用线程池，而且线程池要大于并发数，否则会出现redis超时   */  private static JedisPool jedis = JedisUtil.getPool();  public static void click() &#123;    jedis.getResource().incrBy(&quot;hisen&quot;, 1);  &#125;  public static int getCount() &#123;    return Integer.parseInt(jedis.getResource().get(&quot;hisen&quot;));  &#125;  public static void declare() &#123;    jedis.getResource().del(&quot;hisen&quot;);    jedis.close();  &#125;&#125;
2.2 线程类,模拟点击package com.hisen.thread.count_click_by_redis;/** * @author hisenyuan * @description 执行点击的线程类 */public class CountClickByRedisThread extends Thread&#123;  private int id;  public CountClickByRedisThread(int id) &#123;    this.id = id;  &#125;  @Override  public void run() &#123;    super.run();    ClickRedis.click();    int count = ClickRedis.getCount();    System.out.println(&quot;task:&quot; + id + &quot;\t 执行完毕\t线程编号：&quot; + this.getId() + &quot;\t当前值：&quot; + count);  &#125;&#125;
2.3 主线程 - 启动类
package com.hisen.thread.count_click_by_redis;import Java.util.concurrent.ArrayBlockingQueue;import Java.util.concurrent.ThreadPoolExecutor;import Java.util.concurrent.TimeUnit;public class Main &#123;  public static void main(String[] args) throws InterruptedException &#123;    /**     * 5 - corePoolSize：核心池的大小     * 10 - maximumPoolSize：线程池最大线程数，它表示在线程池中最多能创建多少个线程     * 200 - keepAliveTime：表示线程没有任务执行时最多保持多久时间会终止。     * unit - unit：参数keepAliveTime的时间单位，有7种取值     * workQueue：一个阻塞队列，用来存储等待执行的任务     */    ThreadPoolExecutor executor = new ThreadPoolExecutor(        50,        100,        200,        TimeUnit.MICROSECONDS,        new ArrayBlockingQueue&lt;Runnable&gt;(50));    // 开启50个线程    for (int i = 0; i &lt; 50; i++) &#123;      executor.execute(new CountClickByRedisThread(i));    &#125;    System.out.println(&quot;已经开启所有的子线程&quot;);    // 启动一次顺序关闭，执行以前提交的任务，但不接受新任务。    executor.shutdown();    // 判断所有线程是否已经执行完毕    while (true) &#123;      if (executor.isTerminated()) &#123;        System.out.println(&quot;所有的子线程都结束了！&quot;);        // 清除redis数据        ClickRedis.declare();        break;      &#125;      Thread.sleep(100);    &#125;  &#125;&#125;

springmvc正常情况下redirect并且设置指定响应码，异常情况下返回json数据
背景介绍需求就是正常情况下能redirect到指定的页面异常的情况下，能够返回JSON格式的错误信息正常情况和异常情况都需要设置HTTP Code
代码实现@RequestMapping(value = &quot;/test&quot;, method = RequestMethod.POST)public String webCharge(HttpServletRequest request, HttpServletResponse response) &#123;    if (1==1) &#123;        response.setStatus(200);        return &quot;redirect:https://github.com/hisenyuan&quot;;    &#125; else &#123;        try &#123;            response.setStatus(405);            response.getWriter().write(JSON.toJSONString(&quot;hisenyuan&quot;));            return null;        &#125; catch (IOException e) &#123;            e.printStackTrace();            return &quot;&quot;;        &#125;    &#125;&#125;

Thymeleaf简介前面的例子我们使用的视图技术主要是JSP。JSP的优点是它是Java EE容器的一部分，几乎所有Java EE服务器都支持JSP。缺点就是它在视图表现方面的功能很少，假如我们想迭代一个数组之类的，只能使用&lt;% %&gt;来包括Java语句进行。虽然有标准标签库（JSTL）的补足，但是使用仍然不太方便。另外JSP只能在Java EE容器中使用，如果我们希望渲染电子邮件之类的，JSP就无能为力了。 Java生态圈广泛，自然有很多视图框架，除了JSP之外，还有Freemarker、Velocity、Thymeleaf等很多框架。Thymeleaf的优点是它是基于HTML的，即使视图没有渲染成功，也是一个标准的HTML页面。因此它的可读性很不错，也可以作为设计原型来使用。而且它是完全独立于Java ee容器的，意味着我们可以在任何需要渲染HTML的地方使用Thymeleaf。 Thymeleaf也提供了spring的支持，我们可以非常方便的在Spring配置文件中声明Thymeleaf Beans，然后用它们渲染视图。 改造 - 由jsp到Thymeleaf 引入依赖
&lt;!--thymeleaf模版 spring4.x--&gt;&lt;dependency&gt; &lt;groupId&gt;org.thymeleaf&lt;/groupId&gt; &lt;artifactId&gt;thymeleaf-spring4&lt;/artifactId&gt; &lt;version&gt;3.0.5.RELEASE&lt;/version&gt;&lt;/dependency&gt;
配置ViewResolver(在spring的xml文件里)
&lt;!-- 配置ViewResolver 使用：thymeleaf 模版引擎--&gt; &lt;bean id=&quot;templateResolver&quot; class=&quot;org.thymeleaf.spring4.templateresolver.SpringResourceTemplateResolver&quot;&gt; &lt;property name=&quot;prefix&quot; value=&quot;/WEB-INF/templates/&quot;/&gt; &lt;property name=&quot;suffix&quot; value=&quot;.html&quot;/&gt; &lt;property name=&quot;templateMode&quot; value=&quot;HTML5&quot;/&gt; &lt;!-- 缓存--&gt; &lt;property name=&quot;cacheable&quot; value=&quot;false&quot;/&gt; &lt;/bean&gt; &lt;bean id=&quot;templateEngine&quot; class=&quot;org.thymeleaf.spring4.SpringTemplateEngine&quot;&gt; &lt;property name=&quot;templateResolver&quot; ref=&quot;templateResolver&quot;/&gt; &lt;/bean&gt; &lt;bean class=&quot;org.thymeleaf.spring4.view.ThymeleafViewResolver&quot;&gt; &lt;property name=&quot;templateEngine&quot; ref=&quot;templateEngine&quot;/&gt; &lt;property name=&quot;order&quot; value=&quot;1&quot;/&gt; &lt;property name=&quot;characterEncoding&quot; value=&quot;UTF-8&quot;/&gt; &lt;/bean&gt;
接下来就可以直接使用了，跟之前的jsp没有什么不同
@RequestMapping(value = &quot;/listpageplug/&#123;start&#125;&quot;, method = RequestMethod.GET)private String listPagePlug(@PathVariable(&quot;start&quot;) String start, Model model) &#123; PageHelper.startPage(Integer.valueOf(start), 20); List&lt;Book&gt; readingList = bookService.getListPlug(); model.addAttribute(&quot;books&quot;, readingList); return &quot;readingList&quot;;&#125;
到这里就改造完了，接下来就是Thymeleaf的各种用法了 这里举一个循环遍历的例子,后台返回了books对象集合 &lt;!--判断是否为空--&gt;&lt;tbody th:unless=&quot;$&#123;#lists.isEmpty(books)&#125;&quot;&gt; &lt;!--循环--&gt; &lt;tr th:each=&quot;book : $&#123;books&#125;&quot;&gt; &lt;td th:text=&quot;$&#123;book.bookId&#125;&quot;&gt;&lt;/td&gt; &lt;td th:text=&quot;$&#123;book.name&#125;&quot;&gt;&lt;/td&gt; &lt;td th:text=&quot;$&#123;book.number&#125;&quot;&gt;&lt;/td&gt; &lt;td&gt; &lt;a href=&quot;&lt;%=appPath%&gt;/book/detail/$&#123;book.bookId&#125;&quot;&gt;详情&lt;/a&gt; | &lt;a href=&quot;&lt;%=appPath%&gt;/book/del/$&#123;book.bookId&#125;&quot;&gt;删除&lt;/a&gt; &lt;/td&gt; &lt;/tr&gt;&lt;/tbody&gt; 参考 thymeleaf官方指南 新一代Java模板引擎Thymeleaf Thymeleaf基本知识 thymeleaf总结文章 Thymeleaf 模板的使用 thymeleaf 学习笔记

一、背景业务当中多处用到线程池进行异步处理;为了得知线程池设置是否合理，故需要增加线程池监控;常见的实现方式：

org.springframework.scheduling.concurrent.ScheduledExecutorTask
org.springframework.scheduling.annotation.Scheduled

本文使用1的方式实现，主要是方便进行配置，可以托管多个任务;
二、效果预览taskName:pool1-monitor. taskCount:820, completedTaskCount:820, largestPoolSize:30, poolSize:30, activeCount:0, corePoolSize:30, maximumPoolSize:50, queueSize:0taskName:pool2-monitor. taskCount:1703, completedTaskCount:1703, largestPoolSize:30, poolSize:30, activeCount:0, corePoolSize:30, maximumPoolSize:50, queueSize:0taskName:pool3-monitor. taskCount:820, completedTaskCount:448, largestPoolSize:30, poolSize:30, activeCount:30, corePoolSize:30, maximumPoolSize:50, queueSize:342

三、监控逻辑代码如下:

package com.hisen.thread.monitor.threadpool;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;import Java.util.List;import Java.util.concurrent.ThreadPoolExecutor;/** * @author hisenyuan * @date 2019-09-05 19:45 */public class ThreadPoolMonitor implements Runnable &#123;    private static final Logger LOGGER = LoggerFactory.getLogger(ThreadPoolMonitor.class);    // xml中注入    private List&lt;ThreadPoolTaskExecutor&gt; pools;    @Override    public void run() &#123;        monitorHandle(pools);    &#125;    private void monitorHandle(List&lt;ThreadPoolTaskExecutor&gt; pools) &#123;        pools.forEach(this::handleExecutor);    &#125;    private void handleExecutor(ThreadPoolTaskExecutor p) &#123;        ThreadPoolExecutor threadPoolExecutor = p.getThreadPoolExecutor();        // 线程池需要执行的任务数        long taskCount = threadPoolExecutor.getTaskCount();        // 线程池在运行过程中已完成的任务数        long completedTaskCount = threadPoolExecutor.getCompletedTaskCount();        // 曾经创建过的最大线程数        long largestPoolSize = threadPoolExecutor.getLargestPoolSize();        // 线程池里的线程数量        long poolSize = threadPoolExecutor.getPoolSize();        // 线程池里活跃的线程数量        long activeCount = threadPoolExecutor.getActiveCount();        // 配置的核心线程数        int corePoolSize = threadPoolExecutor.getCorePoolSize();        // 配置的最大线程数        int maximumPoolSize = threadPoolExecutor.getMaximumPoolSize();        // 当前线程池队列的个数        int queueSize = threadPoolExecutor.getQueue().size();        // 线程池前缀名称        String threadNamePrefix = p.getThreadNamePrefix();        LOGGER.info(&quot;taskName:&#123;&#125;monitor. taskCount:&#123;&#125;, completedTaskCount:&#123;&#125;, largestPoolSize:&#123;&#125;, poolSize:&#123;&#125;, activeCount:&#123;&#125;, corePoolSize:&#123;&#125;, maximumPoolSize:&#123;&#125;, queueSize:&#123;&#125;&quot;                , threadNamePrefix                , taskCount                , completedTaskCount                , largestPoolSize                , poolSize                , activeCount                , corePoolSize                , maximumPoolSize                , queueSize);    &#125;    public List&lt;ThreadPoolTaskExecutor&gt; getPools() &#123;        return pools;    &#125;    public void setPools(List&lt;ThreadPoolTaskExecutor&gt; pools) &#123;        this.pools = pools;    &#125;&#125;

四、spring xml配置&lt;!-- ### 线程池监控 开始 ### --&gt;&lt;bean id=&quot;threadPoolMonitorRunnable&quot; class=&quot;com.hisen.thread.monitor.threadpool.ThreadPoolMonitor&quot;&gt;    &lt;property name=&quot;pools&quot;&gt;        &lt;list&gt;            &lt;ref bean=&quot;pool1&quot; /&gt;            &lt;ref bean=&quot;pool2&quot; /&gt;            &lt;ref bean=&quot;pool3&quot; /&gt;        &lt;/list&gt;    &lt;/property&gt;&lt;/bean&gt;&lt;!-- 定时执行的线程池 --&gt;&lt;bean id=&quot;threadPoolMonitorTask&quot; class=&quot;org.springframework.scheduling.concurrent.ScheduledExecutorTask&quot;&gt;    &lt;property name=&quot;runnable&quot; ref=&quot;threadPoolMonitorRunnable&quot;/&gt;    &lt;!-- 延迟时间，单位ms --&gt;    &lt;property name=&quot;delay&quot; value=&quot;150000&quot;/&gt;    &lt;!-- 间隔时间，单位ms --&gt;    &lt;property name=&quot;period&quot; value=&quot;5000&quot;/&gt;&lt;/bean&gt;&lt;!-- 任务调度 --&gt;&lt;bean id=&quot;scheduledExecutorFactoryBean&quot; class=&quot;org.springframework.scheduling.concurrent.ScheduledExecutorFactoryBean&quot;&gt;    &lt;!-- 执行任务的线程池个数 --&gt;    &lt;property name=&quot;poolSize&quot; value=&quot;1&quot; /&gt;    &lt;!-- 任务列表 --&gt;    &lt;property name=&quot;scheduledExecutorTasks&quot;&gt;        &lt;list&gt;            &lt;ref bean=&quot;threadPoolMonitorTask&quot;/&gt;        &lt;/list&gt;    &lt;/property&gt;&lt;/bean&gt;&lt;!-- ### 线程池监控 结束 ### --&gt;

零、背景最近做压力测试，不同的系统的机器监控数据差异明显A 系统：CPU 高 load 低B 系统：CPU 低 load 高
那么是什么导致 A B 系统出现这种情况？CPU 高了系统肯定跑不动了，那么 load 多高代表系统跑不动呢？
一、解释
A 系统的原因  CPU 很忙，没有等待其它资源，瓶颈在 CPU。
B 系统的原因  等待磁盘 I&#x2F;O 完成的进程过多，导致进程队列长度过大，  但是 CPU 运行的进程却很少，这样就导致负载过大，但 CPU 使用率低，瓶颈不在 CPU，可能在 I&#x2F;O。

二、load averages 知识
Linux 系统下代表的是 system load averages。

Linux load averages track not just runnable tasks, but also tasks in the uninterruptible sleep state.  Linux 平均负载不仅跟踪可运行的任务，还跟踪处于不可中断睡眠状态的任务。

On Linux, load averages are (or try to be) “system load averages”, for the system as a whole, measuring the number of threads that are working and waiting to work (CPU, disk, uninterruptible locks). Put differently, it measures the number of threads that aren’t completely idle. Advantage: includes demand for different resources.  在 Linux 上，负载平均值是(或试图是)“系统负载平均值” ，对于整个系统来说，测量正在工作和等待工作的线程数(CPU、磁盘、不可中断锁)。换句话说，它测量的是没有完全空闲的线程数量。优势: 包括对不同资源的需求。

In 1993, a Linux engineer found a nonintuitive case with load averages, and with a three-line patch changed them forever from “CPU load averages” to what one might call “system load averages.” His change included tasks in the uninterruptible state, so that load averages reflected demand for disk resources and not just CPUs.  1993年，一位 Linux 工程师发现了一个与平均负载不直观的案例，一个三行补丁永远地将它们从“ CPU 负载平均值”改变为人们可能称之为“系统负载平均值”他的更改包括处于不可中断状态的任务，因此平均负载反映了对磁盘资源的需求，而不仅仅是 cpu。


三、总结
linux load averages 数字大，代表系统压力大;



load 高可能的原因有(CPU、I&#x2F;O、不可中断锁);
load 1min load 5min load 15min，从左到右递增说明负载在增加，递减说明负载在降低;
负载多大才算高，没有定论，得看是否影响业务，如果业务正常那多半是没有问题的;

四、load 优化
优化算法，减少 CPU 计算;
减少 I&#x2F;O 交互的次数，以及大小;
分布式系统水平扩展更多的机器;

五、参考
Linux Load Averages: Solving the Mystery (发表于 2017 年)
理解Linux系统负荷 （发表于 2011 年）
Linux中CPU使用率低负载高

一、题目Valid Sudoku链接
题目要求：Determine if a 9x9 Sudoku board is valid. Only the filled cells need to be validated according to the following rules:

Each row must contain the digits 1-9 without repetition.
Each column must contain the digits 1-9 without repetition.
Each of the 9 3x3 sub-boxes of the grid must contain the digits 1-9 without repetition.

每一行都不能重复1-9每一列都不能重复1-9每个33的小格子(99分为9个3*3)不能重复
二、解题分析
每一行每一列的数据，我们可以通过遍历二维数组解决；
每个33的怎么解决呢？还是遍历二维数组，循环大(99)的二维数组时，符合条件再循环小(3*3)数组;
怎么判断没有重复？方法很多，这里通过数组下标计数，数组初始值为0，根据下标+1，+1之后如果发现&gt;1那么返回错误;

开始解题的时候可以一个大循环解决一个小问题，后续再把循环合并即可;开始的时候我是写了三个双重for循环：

解决行重复判断问题;
解决列重复判断问题;
解决子矩阵重复判断问题;

当发现每一步都可行之后，尝试着合并，以减少时间复杂度;
三、代码样例public static boolean isValidSudoku(char[][] board) &#123;    // 处理 9 * 9    for (int i = 0; i &lt; board.length; i++) &#123;        int[] rowFlag = new int[10];        int[] columnFlag = new int[10];        for (int j = 0; j &lt; board.length; j++) &#123;            char row = board[i][j];            char column = board[j][i];            if (check(rowFlag, row)) &#123;                return false;            &#125;            if (check(columnFlag, column)) &#123;                return false;            &#125;            // 处理 3 * 3            if (i % 3 == 0 &amp;&amp; j % 3 == 0) &#123;                int[] smallFlag = new int[10];                for (int k = i; k &lt; i + 3; k++) &#123;                    for (int l = j; l &lt; j + 3; l++) &#123;                        char now = board[k][l];                        if (check(smallFlag, now)) &#123;                            return false;                        &#125;                    &#125;                &#125;            &#125;        &#125;    &#125;    return true;&#125;

四、代码详情可运行demo

github地址：ValidSudoku.Java

一、权重算法权重算法一般在路由里面用的比较多，分布式环境下对等的服务有多个，加权随机选出一个服务来调用；
可能还有其他方面的用途，下面的代码简单的实现了这个权重，本质上就用到了数组，随机下标；
二、代码概览public static void main(String[] args) &#123;    String[] weight = &#123;&quot;A&quot;, &quot;A&quot;, &quot;A&quot;, &quot;A&quot;, &quot;A&quot;, &quot;B&quot;, &quot;B&quot;, &quot;B&quot;, &quot;C&quot;, &quot;C&quot;&#125;;    final int times = 500000;    final long hashStart = System.currentTimeMillis();    List&lt;String&gt; hashRes = getList4Hash(weight, times);    printRes(&quot;Hash&quot;, hashStart, hashRes);    final long randomStart = System.currentTimeMillis();    List&lt;String&gt; randomRes = getList4Random(weight, times);    printRes(&quot;Random&quot;, randomStart, randomRes);//        Hash          use millis: 931//        A:49.92%//        B:29.99%//        C:20.09%//        Random        use millis: 50//        A:50.08%//        B:29.93%//        C:19.99%&#125;

三、完整代码
github:show all code
package com.hisen.algorithms;import com.google.common.collect.Lists;import Java.text.NumberFormat;import Java.util.List;import Java.util.Map;import Java.util.Random;import Java.util.UUID;import Java.util.function.Function;import Java.util.stream.Collectors;/** * @Author hisenyuan * @Description $end$ * @Date 2019/3/21 21:04 */public class WeightAlgorithm &#123;    public static void main(String[] args) &#123;        String[] weight = &#123;&quot;A&quot;, &quot;A&quot;, &quot;A&quot;, &quot;A&quot;, &quot;A&quot;, &quot;B&quot;, &quot;B&quot;, &quot;B&quot;, &quot;C&quot;, &quot;C&quot;&#125;;        final int times = 500000;        final long hashStart = System.currentTimeMillis();        List&lt;String&gt; hashRes = getList4Hash(weight, times);        printRes(&quot;Hash&quot;, hashStart, hashRes);        final long randomStart = System.currentTimeMillis();        List&lt;String&gt; randomRes = getList4Random(weight, times);        printRes(&quot;Random&quot;, randomStart, randomRes);//        Hash          use millis: 931//        A:49.92%//        B:29.99%//        C:20.09%//        Random        use millis: 50//        A:50.08%//        B:29.93%//        C:19.99%    &#125;    private static void printRes(String method, long start, List&lt;String&gt; resList) &#123;        final Map&lt;String, Long&gt; collect = resList.stream().collect(Collectors.groupingBy(Function.identity(), Collectors.counting()));        final double a = collect.get(&quot;A&quot;);        final double b = collect.get(&quot;B&quot;);        final double c = collect.get(&quot;C&quot;);        final double sum = a + b + c;        NumberFormat nt = NumberFormat.getPercentInstance();        nt.setMinimumFractionDigits(2);        System.out.println(method + &quot;\t use millis: &quot; + (System.currentTimeMillis() - start));        System.out.println(&quot;A&quot; + &quot;:&quot; + nt.format(a / sum));        System.out.println(&quot;B&quot; + &quot;:&quot; + nt.format(b / sum));        System.out.println(&quot;C&quot; + &quot;:&quot; + nt.format(c / sum));    &#125;    private static List&lt;String&gt; getList4Hash(String[] weight, int times) &#123;        List&lt;String&gt; result = Lists.newArrayList();        for (int i = 0; i &lt; times; i++) &#123;            final String a = UUID.randomUUID().toString() + System.currentTimeMillis();            final int hash = a.hashCode();            final int index = hash &gt; 0 ? hash : -hash;            final String res = weight[index % weight.length];            result.add(res);        &#125;        return result;    &#125;    private static List&lt;String&gt; getList4Random(String[] weight, int times) &#123;        List&lt;String&gt; result = Lists.newArrayList();        Random random = new Random();        for (int i = 0; i &lt; times; i++) &#123;            final int index = random.nextInt(weight.length);            final String res = weight[index];            result.add(res);        &#125;        return result;    &#125;&#125;

零、背景最近在做数据迁移为了加速迁移速度其中就需要把查询到的数据( max 100 条)拆分成 5 份，然后执行 5 个子任务，加速处理
一、代码1.1 常规做法public static &lt;T&gt; List&lt;List&lt;T&gt;&gt; split2(List&lt;T&gt; lists, int subCount) &#123;    if (CollectionUtils.isEmpty(lists) || subCount &lt; 1) &#123;        return null;    &#125;    List&lt;List&lt;T&gt;&gt; result = new ArrayList&lt;&gt;();    int size = lists.size();    int count = (size + subCount - 1) / subCount;    for (int i = 0; i &lt; count; i++) &#123;        List&lt;T&gt; subList = lists.subList(i * subCount, (Math.min((i + 1) * subCount, size)));        result.add(subList);    &#125;    return result;&#125;

1.2 新颖做法
public static &lt;T&gt; List&lt;List&lt;T&gt;&gt; split(List&lt;T&gt; lists, int subCount) &#123;    if (CollectionUtils.isEmpty(lists) || subCount &lt; 1) &#123;        return null;    &#125;    // 简约的计算分桶次数，避免判断是否有余数，再+1    int splitTimes = (lists.size() + subCount - 1) / subCount;    return Stream            // 每次递增指定子列表个数            .iterate(0, n -&gt; n + subCount)            // 限制循环次数            .limit(splitTimes)            // 转换成想要的结果            .map(item -&gt; lists.stream()                    // 跳过之前的下标                    .skip(item)                    // 限制每次的个数为子表个数                    .limit(subCount)                    // 转换为子列表                    .collect(Collectors.toList()))            // 转换为主列表            .collect(Collectors.toList());&#125;
