3.3 压测代码压测教程：JMH 使用参考
import com.google.api.client.util.Lists;import org.openjdk.jmh.annotations.Benchmark;import org.openjdk.jmh.annotations.BenchmarkMode;import org.openjdk.jmh.annotations.Fork;import org.openjdk.jmh.annotations.Measurement;import org.openjdk.jmh.annotations.Mode;import org.openjdk.jmh.annotations.Scope;import org.openjdk.jmh.annotations.Setup;import org.openjdk.jmh.annotations.State;import org.openjdk.jmh.annotations.Warmup;import org.springframework.util.CollectionUtils;import Java.util.ArrayList;import Java.util.List;import Java.util.stream.Collectors;import Java.util.stream.Stream;/** * @author hisenyuan * @date 2022/2/18 20:05 */// 默认的 State，每个测试线程分配一个实例@State(Scope.Thread)// 如果 fork 数是 2 的话，则 JMH 会 fork 出两个进程来进行测试。@Fork(1)// 预热的次数 3 次基准测试(不是执行三次方法)@Warmup(iterations = 1)// 基准执行次数 10 次(参数含义同上)@Measurement(iterations = 10)@BenchmarkMode(Mode.Throughput)public class ListSplit &#123;    private static final List&lt;Integer&gt; INTEGERS = Lists.newArrayList();    @Setup    public void init() &#123;        List&lt;Integer&gt; list = Stream.iterate(0, n -&gt; n + 1)                .limit(1000)                .collect(Collectors.toList());        INTEGERS.addAll(list);    &#125;    @Benchmark    public void splitTest()&#123;        List&lt;List&lt;Integer&gt;&gt; listList = split(INTEGERS, 3);    &#125;    @Benchmark    public void split2Test()&#123;        List&lt;List&lt;Integer&gt;&gt; listList = split2(INTEGERS, 3);    &#125;    public static &lt;T&gt; List&lt;List&lt;T&gt;&gt; split(List&lt;T&gt; lists, int subCount) &#123;        // 简约的计算分桶次数，避免判断是否有余数，再+1        int splitTimes = (lists.size() + subCount - 1) / subCount;        return Stream                // 每次递增指定子列表个数                .iterate(0, n -&gt; n + subCount)                // 限制循环次数                .limit(splitTimes)                // 转换成想要的结果                .map(item -&gt; lists.stream()                        // 跳过之前的下标                        .skip(item)                        // 限制每次的个数为子表个数                        .limit(subCount)                        // 转换为子列表                        .collect(Collectors.toList()))                // 转换为主列表                .collect(Collectors.toList());    &#125;    public static &lt;T&gt; List&lt;List&lt;T&gt;&gt; split2(List&lt;T&gt; list, int len) &#123;        if (CollectionUtils.isEmpty(list) || len &lt; 1) &#123;            return null;        &#125;        List&lt;List&lt;T&gt;&gt; result = new ArrayList&lt;&gt;();        int size = list.size();        int count = (size + len - 1) / len;        for (int i = 0; i &lt; count; i++) &#123;            List&lt;T&gt; subList = list.subList(i * len, (Math.min((i + 1) * len, size)));            result.add(subList);        &#125;        return result;    &#125;

四、后话
其中不错的一点我觉得是
int splitTimes = (lists.size() + subCount - 1) / subCount;
这样巧妙的计算，避免了先取模，后判断是否有余数的繁杂。这个不是我想到的，也不知道怎么通过数学证明，但是这样就是对的 &#x3D;&#x3D;
