一、程序说明 可以以web的方式查看，也可以生成一个图片 直接go run输出的是一丢乱码(图片) 需要go build 然后运行程序(具体看代码里面注释)
具体的内容可以看下面的程序代码(虽然是抄书) 二、程序代码 2.1 基本程序package mainimport ( &quot;image&quot; &quot;image/color&quot; &quot;image/gif&quot; &quot;io&quot; &quot;log&quot; &quot;math&quot; &quot;math/rand&quot; &quot;net/http&quot; &quot;os&quot; &quot;time&quot;)var palette = []color.Color&#123;color.White, color.Black&#125;const ( whiteIndex = 0 // 画板中的第一种颜色 blackIndex = 1 // 画板中的下一种颜色)func main() &#123; rand.Seed(time.Now().UTC().UnixNano()) if len(os.Args) &gt; 1 &amp;&amp; os.Args[1] == &quot;web&quot; &#123; handler := func(w http.ResponseWriter, r *http.Request) &#123; lissajous(w) &#125; http.HandleFunc(&quot;/&quot;, handler) log.Fatal(http.ListenAndServe(&quot;localhost:8000&quot;, nil)) return &#125; lissajous(os.Stdout)&#125;func lissajous(out io.Writer) &#123; const ( cycles = 5 // 完整的x振荡器变化的个数 res = 0.001 // 角度分辨率 size = 100 // 图像画布包含 nframes = 64 // 动画中的帧数 delay = 8 // 以10ms为单位的帧间延迟 ) freq := rand.Float64() * 3.0 // y振荡器的相对频率 anim := gif.GIF&#123;LoopCount: nframes&#125; phase := 0.0 // phase difference for i := 1; i &lt; nframes; i++ &#123; rect := image.Rect(0, 0, 2*size+1, 2*size+1) img := image.NewPaletted(rect, palette) for t := 0.0; t &lt; cycles*2*math.Pi; t += res &#123; x := math.Sin(t) y := math.Sin(t*freq + phase) img.SetColorIndex(size+int(x*size+0.5),size+int(y*size+0.5),blackIndex) &#125; phase +=0.1 anim.Delay = append(anim.Delay,delay) anim.Image = append(anim.Image,img) &#125; gif.EncodeAll(out,&amp;anim) // 注意：忽略编码错误（直接运行输出的是一堆乱码） // go build lissajous.go // ./lissajous &gt;out.gif # 生成一个图片 // ./lissajous web # 开启一个web服务，可以浏览器访问 localhost:8000&#125;
2.2 改进型程序，也是课后练习package mainimport ( &quot;image&quot; &quot;image/color&quot; &quot;image/gif&quot; &quot;io&quot; &quot;log&quot; &quot;math&quot; &quot;math/rand&quot; &quot;net/http&quot; &quot;os&quot; &quot;time&quot;)// 颜色代码数组var palette = []color.Color&#123;color.Black, color.RGBA&#123;199, 237, 204, 0xff&#125;, color.RGBA&#123;102, 53, 204, 0xff&#125;&#125;func main() &#123; rand.Seed(time.Now().UTC().UnixNano()) // 判断传入参数 如果有web,就启动一个web服务器 if len(os.Args) &gt; 1 &amp;&amp; os.Args[1] == &quot;web&quot; &#123; handler := func(w http.ResponseWriter, r *http.Request) &#123; lissajous(w) &#125; http.HandleFunc(&quot;/&quot;, handler) log.Fatal(http.ListenAndServe(&quot;localhost:8000&quot;, nil)) return &#125; lissajous(os.Stdout)&#125;func lissajous(out io.Writer) &#123; const ( cycles = 5 // 完整的x振荡器变化的个数 res = 0.001 // 角度分辨率 size = 100 // 图像画布包含 nframes = 64 // 动画中的帧数 delay = 8 // 以10ms为单位的帧间延迟 ) freq := rand.Float64() * 3.0 // y振荡器的相对频率 anim := gif.GIF&#123;LoopCount: nframes&#125; phase := 0.0 // phase difference for index,i :=0, 1; i &lt; nframes; i++ &#123; rect := image.Rect(0, 0, 2*size+1, 2*size+1) img := image.NewPaletted(rect, palette) for t := 0.0; t &lt; cycles*2*math.Pi; t += res &#123; x := math.Sin(t) y := math.Sin(t*freq + phase) img.SetColorIndex(size+int(x*size+0.5), size+int(y*size+0.5), uint8(index)) &#125; // 控制变色频率，生成颜色数组下标 index = i % 3 phase += 0.1 anim.Delay = append(anim.Delay, delay) anim.Image = append(anim.Image, img) &#125; gif.EncodeAll(out, &amp;anim) // 注意：忽略编码错误（直接运行输出的是一堆乱码） // go build lissajous.go // ./lissajous &gt;out.gif # 生成一个图片 // ./lissajous web # 开启一个web服务，可以浏览器访问 localhost:8000&#125;

一些简单的黑产攻防介绍

修改前置摄像头，直接播放本地视频或者图片(色情诈骗、网约车司机人脸识别);
恶意注册靶机系统：黑卡猫池、群控、云控、箱控(12个主板，模拟120台手机);
模拟点击脚本在黑产中使用比例逐年增高，主要是效果好很难区分是否为真实用户;
ROS软路由(可管理250个IP)、秒拨(每次拨号IP改变);



黑产变现的渠道主要有：羊毛、引流(注册账号发布信息);
很多黑产行为在单个平台来讲都是一次性活动;
改机工具：类沙箱，可以更改大量手机信息，提供快照功能，方便上下游复现现场环境，权限高，欺骗效果好;
针对改机工具一般都进行恶意环境检测，指令集中是否有hook、cpu架构、文件目录等;
防护方针：增加黑产的量化攻击成本(时间、资金);
给出模糊的错误提示，而不是准确的，否则黑产很容易试出策略;
不要在注册环节就大量拦截，要考虑用户体验，也要收集黑产行为信息，杀量化攻击;
忘记密码可能会被利用，找回密码的机制要严格审核(匹配通讯录等);
黑产资源成本高，全网来讲资源重复利用率高;
IP资源、定位、手机、脚本、改机工具、云控等方便规模化，精细化运作;

从中不难看出源头是黑卡、被利用的宽带账号、也有可能是路由器、物联网设备等;运营商加强实名认证宽带拨号频率限制网络设备安全加固，关闭特殊权限端口，禁用弱密码
打击网络黑产交易，防止黑产规模化，产业化趋势;
蜜罐系统收集黑产IP提供IP代理给黑产使用了解对方信息

定义最多有两棵子树的有序树，称为二叉树。二叉树是一种特殊的树。 性质这里规定二叉树的根结点的层次为1。
性质1：则二叉树的第i 层最多有2i-1个结点（在此二叉树的层次从1开始，i≥1） 性质2：深度为k的二叉树最多有2k-1个结点。(k≥1) 性质3：对任何一棵二叉树T, 如果其叶结点个数为n0, 度为2的非叶结点个数为n2, 则有 n0 &#x3D; n2 + 1 性质4：具有 n(n&gt;0)个结点的完全二叉树的深度为⎣log2n⎦+1；⎦x⎦表示不超过x的最大整数。 性质5：如果对一棵有n个结点的完全二叉树的结点按层序编号（从第1层到第⎣l og2n⎦ +1层，每层从左到右）,则对任一结点i（1≤i≤n),有：5.1 (1)如果i&#x3D;1，则结点i无双亲，是二叉树的根；如果i&gt;1，则其双亲是结点⎣i&#x2F;2⎦。5.2 (2) 如果2i&lt;&#x3D;n, 则结点i的左孩子结点是2i；否则，结点i为叶子结点，无左孩子结点。5.3 (3)如果2i＋1&lt;&#x3D;n，则结点i的右孩子是结点2i＋1; 否则，结点i为叶子结点，无右孩子结点。
完整代码https://github.com/hisenyuan/btree 二叉链表的实现package com.hisen.interview.tiger20171110.btree;/** * @author : yhx * @date : 2017/11/10 18:42 * @descriptor : 二叉树的 - 二叉链表实现 */public class LinkBTree implements BTree &#123; private Object data; private BTree lChild; private BTree rChild; public LinkBTree() &#123; this.clearTree(); &#125; public LinkBTree(Object data) &#123; this.data = data; this.rChild = null; this.lChild = null; &#125; @Override public void addLfetTree(BTree lChild) &#123; this.lChild = lChild; &#125; @Override public BTree getLfetTree() &#123; return lChild; &#125; @Override public void addRightTree(BTree rChild) &#123; this.rChild = rChild; &#125; @Override public BTree getRightTree() &#123; return rChild; &#125; @Override public void clearTree() &#123; this.data = null; this.rChild = null; this.lChild = null; &#125; @Override public int getDeep() &#123; return deep(this); &#125; @Override public Object getRootData() &#123; return data; &#125; @Override public boolean hasLeftTree() &#123; if (lChild != null) &#123; return true; &#125; return false; &#125; @Override public boolean hasRightTree() &#123; if (rChild != null) &#123; return true; &#125; return false; &#125; @Override public boolean isEmptyTree() &#123; if ((lChild == null &amp;&amp; rChild == null &amp;&amp; data == null) || this == null) &#123; return true; &#125; return false; &#125; @Override public boolean isLeaf() &#123; if (lChild == null &amp;&amp; rChild == null) &#123; return true; &#125; return false; &#125; @Override public void removeLeftTree() &#123; lChild = null; &#125; @Override public void removeRightTree() &#123; rChild = null; &#125; @Override public BTree getRoot() &#123; return this; &#125; @Override public void setRootData() &#123; this.data = data; &#125; @Override public int size() &#123; return size(this); &#125; private int size(BTree bTree) &#123; if (bTree == null) &#123; return 0; &#125; else if (bTree.isLeaf()) &#123; return 1; &#125; else &#123; if (bTree.getLfetTree() == null) &#123; return size(bTree.getRightTree()) + 1; &#125; else if (bTree.getRightTree() == null) &#123; return size(bTree.getLfetTree()) + 1; &#125; else &#123; return size(bTree.getLfetTree()) + size(bTree.getRightTree()) + 1; &#125; &#125; &#125; /** * 计算二叉树的高度 */ private int deep(BTree bTree) &#123; if (bTree.isEmptyTree()) &#123; return 0; &#125; else if (bTree.isLeaf()) &#123; return 1; &#125; else &#123; if (bTree.getLfetTree() == null) &#123; return deep(bTree.getRightTree()) + 1; &#125; else if (bTree.getRightTree() == null) &#123; return deep(bTree.getLfetTree()) + 1; &#125; else &#123; return Math.max(deep(bTree.getLfetTree()), deep(bTree.getRightTree())) + 1; &#125; &#125; &#125;&#125;
二叉树的各种遍历遍历方式：前序、中序、后序、层次
package com.hisen.interview.tiger20171110.btree;import Java.util.LinkedList;/** * @author : yhx * @date : 2017/11/13 12:15 * @descriptor : 二叉树的遍历 */public class OrderBTree implements Visit &#123; /** * 前序遍历 * * @param root 根节点 */ public void preOrder(BTree root) &#123; visit(root); if (root.getLfetTree() != null) &#123; preOrder(root.getLfetTree()); &#125; if (root.getRightTree() != null) &#123; preOrder(root.getRightTree()); &#125; &#125; /** * 中序遍历 * * @param root 根节点 */ public void inOrder(BTree root) &#123; if (root.getLfetTree() != null) &#123; inOrder(root.getLfetTree()); &#125; visit(root); if (root.getRightTree() != null) &#123; inOrder(root.getRightTree()); &#125; &#125; /** * 后序遍历 * @param root 根节点 */ public void postOrder(BTree root) &#123; if (root.getLfetTree() != null) &#123; postOrder(root.getLfetTree()); &#125; if (root.getRightTree() != null) &#123; postOrder(root.getRightTree()); &#125; visit(root); &#125; /** * 层次遍历 - 利用队列 * @param bTree 根节点 */ public void levelOrder(BTree bTree)&#123; if (bTree == null)&#123; return; &#125; LinkedList&lt;BTree&gt; queue = new LinkedList&lt;&gt;(); BTree current = null; // 将根节点入队列 queue.offer(bTree); while (!queue.isEmpty())&#123; // 队头元素出队列 current = queue.poll(); visit(current); // 如果左节点不为空，入队列 if (current.getLfetTree() != null)&#123; queue.offer(current.getLfetTree()); &#125; // 如果右节点不为空，入队列 if (current.getRightTree() != null)&#123; queue.offer(current.getRightTree()); &#125; &#125; &#125; /** * 访问二叉树的节点 * @param bTree 树的节点 */ @Override public void visit(BTree bTree) &#123; System.out.print(bTree.getRootData() + &quot;\t&quot;); &#125;&#125;
