/** * @author hisenyuan * @date 2019-10-25 23:20 */public class CallerAnalyze &#123; public static void main(String[] args) throws IOException &#123; String filePath = &quot;/Users/hisenyuan/yw/yw.log&quot;; ArrayList&lt;CallerTimeVo&gt; callerTimeVos = getCallerTimeVos(filePath); System.out.println(&quot;size:&quot; + callerTimeVos.size()); System.out.printf(&quot;%-20s%-20s%-20s%-20s%-20s%-20s%-20s%-20s&quot;, &quot;yw&quot;, &quot;count&quot;, &quot;min(ms)&quot;, &quot;max(ms)&quot;, &quot;tp50(ms)&quot;, &quot;tp90(ms)&quot;, &quot;tp99(ms)&quot;, &quot;tp999(ms)&quot;); System.out.println(); Map&lt;String, List&lt;CallerTimeVo&gt;&gt; callerMap = callerTimeVos.parallelStream().collect(Collectors.groupingBy(CallerTimeVo::getCaller)); callerMap.entrySet() .stream() .sorted(Comparator.comparingInt(value -&gt; value.getValue().size())) .forEach(stringListEntry -&gt; &#123; String caller = stringListEntry.getKey(); System.out.printf(&quot;%-20s&quot;, caller); List&lt;Long&gt; sorted = stringListEntry.getValue() .parallelStream() .map(CallerTimeVo::getDuration) .sorted(Long::compareTo) .collect(Collectors.toList()); calTime(sorted); &#125;); &#125; private static ArrayList&lt;CallerTimeVo&gt; getCallerTimeVos(String filePath) throws IOException &#123; ArrayList&lt;CallerTimeVo&gt; callerTimeVos = Lists.newArrayList(); Files.asCharSource(new File(filePath), Charset.forName(&quot;UTF-8&quot;)).readLines(new LineProcessor&lt;String&gt;() &#123; @Override public boolean processLine(String line) &#123; // 处理每一行 CallerTimeVo vo = getCreateTimeVo(line); callerTimeVos.add(vo); // false 会中断操作 return true; &#125; @Override public String getResult() &#123; return null; &#125; &#125;); return callerTimeVos; &#125;&#125;

一、背景交代 部署方式：多点 业务概要：处理一批数据，可以失败重试
二、实现方式 主表入一条控制数据，两个控制字段：next，process(0:空闲,1:处理中)，子表具体处理业务 定时任务只扫描主表，通过其他业务字段，加上主表两个控制字段(now&gt;netx,process&#x3D;0)，捞出需要处理的数据 当开始处理数据时候，先更新process&#x3D;1，如果更新成功，说明拿到锁(假装是一个分布式锁，因为两台机器) 如果拿到3的锁，则开始处理子表的业务数据，一次查100条(limit 0,100 desc update_time)，直到子表全部处理完成 如果遇到错误，把错误数据的id存起来，更新子表重试次数，和更新时间，如果达到最大失败次数，更改状态(让4查不出这条数据) 如果遇到当前处理数据的id存在List中，那么说明当前所有的数据都处理过一次了，退出(如果不判断，失败后会无限循环，直到全部成功)
三、伪代码public void process(MainTable mainTable) &#123; // 1. 锁控制表 boolean lock = service.lock(mainTable); LOGGER.info(&quot;lockFlag:,&quot;, lock, &quot;,mainTableId:&quot;, mainTable.getId()); if (!lockFlag) &#123; return; &#125; List&lt;Long&gt; repeatIds = new ArrayList&lt;&gt;(); // 2. 根据主表id，下次扫描时间，每次查询100条 List&lt;SubTable&gt; subTables; do &#123; //扫描子表中的数据 subTables = service.querySub(mainTable.getId(), 100); for (SubTable sub : subTables) &#123; if (repeatIds.contains(batch.getId())) &#123; subTables = null; break; &#125; // 处理业务 handle(mainTable, subTables, repeatIds); &#125; &#125; while (!CollectionUtils.isEmpty(subTables)); // 5. 检查是否全部终态 checkHandleDone(mainTable); // 7. 释放锁 boolean unLock = service.unLock(mainTable); LOGGER.info(&quot;lockFlag:,&quot;, unLock, &quot;,mainTableId:&quot;, mainTable.getId());&#125;

effective Java： 单元素的枚举类型已经成为实现Singleton的最佳方法 理由：
因为枚举单例有序列化和线程安全的保证 避免反射和并发困扰
单例模式模式：完整代码+测试 主要代码： public class EnumSingleton &#123; private EnumSingleton() &#123; &#125; public static EnumSingleton getInstance() &#123; return Singleton.INSTANCE.getInstance(); &#125; private enum Singleton &#123; INSTANCE; private EnumSingleton singleton; Singleton() &#123; singleton = new EnumSingleton(); &#125; public EnumSingleton getInstance() &#123; return singleton; &#125; &#125;&#125;

具体代码如下，这里获取出来的文件大小是准确的
FileInputStream方式获取出来的大小会有差异
NIO与IO的对比详见：NIOCopy.Java
/**   * 利用NIO进行读写文件   *   * @param oldFileName 原文件的路径   * @param newFileName 新文件的路径   */  public static void nioCopy(String oldFileName, String newFileName) &#123;    try &#123;      FileChannel fileChannelIn = new FileInputStream(new File(oldFileName)).getChannel();      FileChannel fileChannelOut = new FileOutputStream(new File(newFileName)).getChannel();      //获取文件大小      long size = fileChannelIn.size();      System.out.printf(&quot;文件大小为：%s byte \n&quot;,size);      //缓冲      ByteBuffer byteBuffer = ByteBuffer.allocate(1024);      long start = System.currentTimeMillis();      while (fileChannelIn.read(byteBuffer) != -1) &#123;        //准备写        byteBuffer.flip();        fileChannelOut.write(byteBuffer);        //准备读        byteBuffer.clear();      &#125;      long end = System.currentTimeMillis();      System.out.printf(&quot;NIO方式复制完成，耗时 %s 秒\n&quot;,(end-start)/1000);      //关闭      fileChannelIn.close();      fileChannelOut.close();    &#125; catch (FileNotFoundException e) &#123;      e.printStackTrace();    &#125; catch (IOException e) &#123;      e.printStackTrace();    &#125;  &#125;

概述布隆过滤器的作用是加快判定一个元素是否在集合中出现的方法。 因为其主要是过滤掉了大部分元素间的精确匹配，故称为过滤器。
其应用场景为需要频繁在一个海量的集合中查找某个元素是否存在。 并且通常，这个值不在集合中。 比如Google chrome用此方法检查一个url是否在恶意url库中。 简单的例子假设有一些字符串，假设有一个字符串a，要在集合B中查找其是否在集合B中。最笨的方法是遍历集合B中的每个元素bi，精确匹配a是否等于bi。若集合B中有N个元素，则最坏情况下需要执行N次精确匹配。 一个改进的方法是将a和B中每个字符串按照特定规则映射为数字，称为hash值。规则可以任意设置。比如取各字符串的首字母和尾字母的编码之乘积，取奇数个字符的编码执行异或，等。将比较字符串问题变成一个比较数字的问题。比较字符串需要从头到尾比较，而数字的比较会快很多。 需要注意的是，当两个字符串相同时，采用相同的映射规则得到的数字一定相同。但当两个字符串不同时，得到的字符串不一定不同。所以，当我们发现两个字符串的hash值相同时，两个字符串不一定相同，所以需要进一步去精确匹配两个字符串是否相同。但采用hash值方法已经能够过滤掉一部分以前需要精确匹配的计算量。仅当hash值相同（假设hash值通过字符串首尾字母计算得来，则当两个字符串首尾字母相同时hash值相同）时才去比较字符串本身。若选择hash值合理，则性能将大幅提高。 布隆过滤器通过将一个字符串使用多个不同的hash值计算方法，映射为多个不同的hash值，当所有这些hash值完全相同时，才认为两个字符串相同。从而进一步降低了放生hash值相同的可能性，从而进一步提高了过滤的性能。 Java代码实现算法使用了md5值来生成n个不同的hash值
package com.hisen.interview;import Java.math.BigInteger;import Java.security.MessageDigest;import Java.security.NoSuchAlgorithmException;import Java.util.ArrayList;/** * 布隆过滤器 - 测试某个元素不存在集合中 * Created by hisenyuan on 2017/9/7 at 8:50. */public class BloomFilter &#123; public static final int NUM_SLOTS = 1024 * 1024 * 8; public static final int NUM_HASH = 8; private BigInteger bitmap = new BigInteger(&quot;0&quot;); public static void main(String[] args) &#123; BloomFilter bf = new BloomFilter(); ArrayList&lt;String&gt; contents = new ArrayList&lt;&gt;(); contents.add(&quot;sldkjelsjf&quot;); contents.add(&quot;ggl;ker;gekr&quot;); contents.add(&quot;wieoneomfwe&quot;); contents.add(&quot;sldkjelsvrnlkjf&quot;); contents.add(&quot;ksldkflefwefwefe&quot;); for (int i = 0; i &lt; contents.size(); i++) &#123; bf.adElement(contents.get(i)); &#125; System.out.println(bf.check(&quot;sldkjelsvrnlkjf&quot;)); System.out.println(bf.check(&quot;sldkjelsvrnkjf&quot;)); &#125; private void adElement(String message) &#123; for (int i = 0; i &lt; NUM_HASH; i++) &#123; int hashCode = getHash(message, i); if (!bitmap.testBit(hashCode)) &#123; bitmap = bitmap.or(new BigInteger(&quot;1&quot;).shiftLeft(hashCode)); &#125; &#125; &#125; private boolean check(String message) &#123; for (int i = 0; i &lt; NUM_HASH; i++) &#123; int hashCode = getHash(message,i); if (this.bitmap.testBit(hashCode))&#123; return false; &#125; &#125; return true; &#125; private int getHash(String message, int i) &#123; try &#123; MessageDigest md5 = MessageDigest.getInstance(&quot;md5&quot;); message = message + String.valueOf(i); byte[] bytes = message.getBytes(); md5.update(bytes); BigInteger bi = new BigInteger(md5.digest()); return Math.abs(bi.intValue()) % NUM_SLOTS; &#125; catch (NoSuchAlgorithmException e) &#123; e.printStackTrace(); &#125; return -1; &#125;&#125;

零、本文背景一个接口的关键指标应该就是响应速度，要想提高响应速度，结果在缓存中最好;那么怎么确定一个合理的缓存时间，以平衡性能与成本呢？我们可以通过记录业务请求，看读取缓存的时间分布，比如 99% 的请求都是 1天内;
近期在做日志分析，找到比较理想的一个缓存过期时间，使 90% 的查询都能被缓存覆盖;发现有些同学不太懂 TP 指标，故写文记录一下。
一、性能指标含义常见指标：TP50、TP80、TP90、TP99、TP999正式解释：TP&#x3D;Top Percentile，Top百分数，是一个统计学术语，与平均数、中位数都是一类;通俗理解：TP99 100ms，99%的查询都能在100ms内返回;本质理解：它是一个分位值，看数据的一个分布;
二、性能指标计算计算方式：拿到所有请求耗时，升序排序，取 99% 位置的数据，就是 TP99;比如说：拿 100 次请求的耗时，升序排序，取第 99 个的数据，就是TP99的值;
具体的代码方式就是，先算出耗时，放入 List ，然后排序，按指定的下标取值即可;
代码如下：

private void calTime(List&lt;Long&gt; timeDurations) &#123;    timeDurations.sort(Long::compareTo);    double tp50 = timeDurations.size() * 0.5;    double tp90 = timeDurations.size() * 0.9;    double tp99 = timeDurations.size() * 0.99;    double tp999 = timeDurations.size() * 0.999;    // 基础统计，包含max、min、count、avg信息;    DoubleSummaryStatistics doubleSummaryStatistics = timeDurations.stream().mapToDouble(Long::longValue).summaryStatistics();    System.out.println(JSON.toJSONString(doubleSummaryStatistics));    // Math.ceil() 向上取整    System.out.println(&quot;tp50:&quot; + timeDurations.get((int) Math.ceil(tp50)));    System.out.println(&quot;tp90:&quot; + timeDurations.get((int) Math.ceil(tp90)));    System.out.println(&quot;tp99:&quot; + timeDurations.get((int) Math.ceil(tp99)));    System.out.println(&quot;tp999:&quot; + timeDurations.get((int) Math.ceil(tp999)));&#125;

