四、代码对比String oriStr = &quot;aa aa aaaa aaa a a a aa aa a&quot;;int times = 100000;// 自定义实现final long start1 = System.nanoTime();for (int i = 0; i &lt; times; i++) &#123;    String splitStr = &quot; &quot;;    findMaxLength(oriStr, splitStr);&#125;final long end1 = System.nanoTime();// 利用 StringTokenizerfinal long start2 = System.nanoTime();for (int i = 0; i &lt; times; i++) &#123;    findMaxLength4StringTokenizer(oriStr);&#125;final long end2 = System.nanoTime();// 利用 Splitfinal long start3 = System.nanoTime();for (int i = 0; i &lt; times; i++) &#123;    String splitStr = &quot; &quot;;    findMaxLength4Split(oriStr, splitStr);&#125;final long end3 = System.nanoTime();System.out.println(&quot;use(nano): &quot; + (end1 - start1) + &quot;, by findMaxLength&quot;);System.out.println(&quot;use(nano): &quot; + (end2 - start2) + &quot;, by findMaxLength4StringTokenizer&quot;);System.out.println(&quot;use(nano): &quot; + (end3 - start3) + &quot;, by findMaxLength4Split&quot;);//        output//        use(nano): 15486049, by findMaxLength//        use(nano): 66060102, by findMaxLength4StringTokenizer//        use(nano): 80844275, by findMaxLength4Split
五、完整代码
