//懒汉模式public class LazySingleton &#123; private static LazySingleton instance = null; private LazySingleton()&#123; super(); &#125; public static LazySingleton getInstance()&#123; if(instance == null)&#123; // 静态方法，使用当前类本身充当进程锁 synchronized(LazySingleton.class)&#123; instance = new LazySingleton(); &#125; &#125; return instance; &#125;&#125;// 饿汉式单例模式public class EagerSingleton &#123; private static EagerSingleton instance = new EagerSingleton(); private EagerSingleton()&#123; super(); &#125; // 不需要同步（类加载时已经初始化，不存在多线程的问题） // 始终只有一个对象 public EagerSingleton getInstance()&#123; return instance; &#125;&#125;
